class Solution {
public:
    long long secondsToFinish(vector<int>& wants, int k) {
        vector<int> left = wants;
        deque<int> line;
        for (int i = 0; i < (int) wants.size(); i++) line.push_back(i);
        long long t = 0;
        while (true) {
            int i = line.front();
            line.pop_front();
            t++;
            if (--left[i] == 0) {
                if (i == k) return t;
            } else line.push_back(i);
        }
    }
};

code.c:
long long secondsToFinish(int* wants, int wantsSize, int k) {
    int n = wantsSize;
    int* left = malloc(n * sizeof(int));
    int* line = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) { left[i] = wants[i]; line[i] = i; }
    int head = 0, size = n;
    long long t = 0;
    while (1) {
        int i = line[head];
        head = (head + 1) % n;
        size--;
        t++;
        if (--left[i] == 0) {
            if (i == k) break;
        } else {
            line[(head + size) % n] = i;
            size++;
        }
    }
    free(left);
    free(line);
    return t;
}

