class Solution {
    public long secondsToFinish(int[] wants, int k) {
        int need = wants[k];
        long total = 0;
        for (int i = 0; i < wants.length; i++)
            total += Math.min(wants[i], i <= k ? need : need - 1);
        return total;
    }
}

