long long secondsToFinish(int* wants, int wantsSize, int k) {
    int need = wants[k];
    long long total = 0;
    for (int i = 0; i < wantsSize; i++) {
        int cap = i <= k ? need : need - 1;
        total += wants[i] < cap ? wants[i] : cap;
    }
    return total;
}
